function [bandarrays,bandsdatafile] = MechBands()%%  program MechBands%%  Compiled by Paul Dawson from codes and scripts from MAE courses, OdfPF, %   pre- and post-processing tools for FEpX, other research projects%   in the Deformation Processes Lab at Cornell University.%%  Driver program for detection of bands of a property or field withing a polycrsytal %    Intent:   find sets of connected elements sharing values a property or%    field variable lying with designated upper and lower threshold values%%    Input:   %             (1) nepermeshname -- string for basename of the .msh file generated by Neper (version 4 or higher)%             (2) framefilebasename -- Basename (with extension .h5) of the MechMet or FEpX output file%             (3) framenumber -- Frame number in the .h5 dataset file to be analyzed%             (4) fieldvariablename -- Field variable name in .h5 file; one scalar value for each element. %             (5) extravariablename -- A second field variable name in .h5 file; one scalar value for each element. %                                      (Available for comparison but not used otherwise.)           %             (6) thresholds -- upper and lower limits of band values for the scalar field given in the datafile%%     Output: (1) sets of elements that form bands within the polycrystal %                   together with the associated field or property data%             (2) graph data for the entire mesh and for the larger bands%             (3) vtk file for visualization%%          clear 'all';status = ' Starting simulation:  Read files with input data.'nepermshname = input('Base name (with extension .msh) of the combined mesh  and microstructure file: ', 's');[meshfile,microstructurefile] = ReadNeperMshFile(nepermshname);phases = microstructurefile.phases;grains = microstructurefile.grains;rotations = microstructurefile.rotations;orientations = microstructurefile.orientations;ngrains=max(grains);%% Set mesh size variables from mesh coordinate and connectivity arrays%[m n]   = size(meshfile.crd);numnp = n;[m n]   = size(meshfile.con);np = meshfile.con';numel = n;nnpe = 10;nspe = 6;nfpe = 4;nps_local = [ 1 2 3 4 5 6; 1 6 5 9 10  7; 1 7 10 8 3 2; 3 8 10 9 5 4 ];existing_eleneigh_string = input('Do Element-Neighbors (.mat) and Graph arrays exist?  If yes, input: 1; if no, enter 0: ', 's');existing_eleneigh_flag  = str2num(existing_eleneigh_string);if(existing_eleneigh_flag==1)       ele_neigh_struc = load([nepermshname,'_neigh.mat']);   ele_neigh = ele_neigh_struc.ele_neigh;             graph_struc = load([nepermshname,'_graph.mat']);   graph_links = graph_struc.graph_links;   graph_link_inv = graph_struc.graph_link_inv;      numlinks = size(graph_links,1);else% create element-to-element connectivity arrays.  For each element, the arrays give the neighboring elements side-by-side%   (that is, elements that share a face and not elements that share only an edge or a node).% first,create the npinv and ele4npf arrays %  npinv stands for nodal point inverse -- for each node what are the elements that use that node%  elenpf gives the freqency (number) of elements for each node (number of non-zero entries in each row of the npinv array) ele4npf = zeros(numnp,1);for iele = 1:1:numel    for jnp = 1:1:nnpe        j1=np(iele,jnp);        ele4npf(j1)=ele4npf(j1)+1;    endendmaxelpernp = max(ele4npf);npinv = zeros(numnp,maxelpernp);ele4npf = zeros(numnp,1);for iele = 1:1:numel       for jnp = 1:1:nnpe        j1=np(iele,jnp);        j2=ele4npf(j1);        npinv(j1,j2+1)=iele;                ele4npf(j1)=ele4npf(j1)+1;    endend% next create the element neighbors array ele_neigh = zeros(nfpe,numel);for iele = 1:1:numel      for jside = 1:1:nfpe               jnp1 = np(iele,nps_local(jside,2));        jnp2 = np(iele,nps_local(jside,4));                ele_neigh1 = zeros(1,ele4npf(jnp1));                for knpi =1:1:ele4npf(jnp1)            kel1 = npinv(jnp1,knpi);                for lnp1 = 1:1:nnpe                  knp1=np(kel1,lnp1);                    if(knp1==jnp1)                         ele_neigh1(knpi) = kel1;                    end                end          end                        ele_neigh2 = zeros(1,ele4npf(jnp1));                for knpi =1:1:ele4npf(jnp2)            kel2 = npinv(jnp2,knpi);                for lnp2 = 1:1:nnpe                  knp2=np(kel2,lnp2);                    if(knp2==jnp2)                         ele_neigh2(knpi) = kel2;                    end                end        end               dummy = intersect(ele_neigh1,ele_neigh2);       dummy2 = size(dummy);        if(dummy2(2)==2)            if(dummy(1)==iele)                ele_neigh(jside,iele) = dummy(2);            end            if(dummy(1)~=iele)                ele_neigh(jside,iele) = dummy(1);            end        end    endendclear ele_neigh1 ele_neigh2 npinv ele4npfsave([nepermshname,'_neigh.mat'],'ele_neigh');% create graph_link array -- for each link, element numbers%     graph_links = double.empty;    source_target = zeros(1,2);      for iele = 1:1:numel                   for jside = 1:1:nfpe          neighbornumber = ele_neigh(jside,iele);          source_target(1) = iele;          source_target(2) = neighbornumber;          if(neighbornumber>iele)              graph_links = cat(1,graph_links,source_target);          end     end        end    % create a graph_link inverse array -- for each element, the link numbers.  numlinks = size(graph_links,1);  graph_link_inv = zeros(nfpe,numel);    for ilink = 1:1:numlinks            is = graph_links(ilink,1);      it = graph_links(ilink,2);           for jside = 1:1:nfpe                 neighbors1 = ele_neigh(jside,is);                for kside = 1:1:nfpe                       neighbors2 = ele_neigh(kside,it);                if(is==neighbors2 & it == neighbors1)           graph_link_inv(jside,neighbors2) = ilink;           graph_link_inv(kside,neighbors1) = ilink;        end                end      end        end      save([nepermshname,'_graph.mat'],'graph_links','graph_link_inv');end framefilebasename = input('Basename (with extension .h5) of the file with simulation results: ', 's'); framenumber = input('Enter the frame number in the .h5 dataset file to be analyzed: ', 's'); fieldvariablename = input('Field variable name in .h5 file: ', 's'); datapath=['/Frame_' framenumber]; datapath = append(datapath,'/'); datapath = append(datapath,fieldvariablename); datafile2 = h5read([framefilebasename '.h5'],datapath); datasize = size(datafile2); datadim = ndims(datasize); if(datasize(2) >= 2) compdatasize  = datasize(1); fielddatasize = datasize(2); datafile = zeros(fielddatasize,1);    for ifield = 1:1:fielddatasize        elfielddata = datafile2(:,ifield);        datafile(ifield) = norm(elfielddata);    end else compdatasize  = 1; fielddatasize = datasize(1); datafile = datafile2; end datamax = max(datafile); datamin = min(datafile);message = ['The minimum value of the field variable is:   ', num2str(datamin)];disp(message)message = ['The maximum value of the field variable is:   ', num2str(datamax)];disp(message)if(fielddatasize~= numel)    status = ' datafile size does not match mesh size -- enter control_c to exit '    pauseendclear datafile2;% %  load extra data files from simulation results to be written to VTK file%     this is done only for plotting purposes after the fact and %     is not part of the mechbands procedure% extrafieldvariablename1 = input('Additional field variable name in .h5 file: ', 's'); datapath=['/Frame_' framenumber '/']; datapath_extra_array1 = append(datapath,extrafieldvariablename1); extradatafile = h5read([framefilebasename '.h5'],datapath_extra_array1);% %  load current coordinates from simulation results to be written to VTK file% datapath_coords =['/Frame_' framenumber,'/','coords']; coords_frame = h5read([framefilebasename '.h5'],datapath_coords); datasize_coords = size(coords_frame);%remove round-off values% apply threshold to field dataprompt_lower = 'Input lower threshold value:  ';lower_threshold = input(prompt_lower);prompt_upper = 'Input upper threshold value:  ';upper_threshold = input(prompt_upper);element_status = zeros(1,numel);element_node = zeros(1,numel);for iele = 1:1:numel    element_node(iele) = iele;    if(datafile(iele) <= upper_threshold & datafile(iele) >= lower_threshold )        element_status(iele) = 1;    endend%  create the graph_weights array.  Weight = 1 for any link that connects%  two elements both with status = 1;  otherwise Weight = 0.graph_weights = zeros(numlinks,1);for ilink = 1:1:numlinks    graph_node1 = graph_links(ilink,1);    graph_node2 = graph_links(ilink,2);    if(element_status(graph_node1)==1 & element_status(graph_node2)==1)        graph_weights(ilink) = 1.;    end end%  create an array of active links to be used with matlab graph utility%  functions to identify sets of connected elements.   num_connects = sum(graph_weights);   connected_links = zeros(num_connects,2);   icntr_cl = 0;   for ilink = 1:1:numlinks    if(graph_weights(ilink)==1.)        icntr_cl = icntr_cl+1;        connected_links(icntr_cl,:) = graph_links(ilink,:);    end   endstatusfile    = Data_Structure_Status(element_status,element_node,graph_weights,connected_links);save([framefilebasename,'_statusfile.mat'],'statusfile');clear connected_links element_node%  create bands within the mesh of connected elements with status=1.nbands = 0;maxbandsize = sum(element_status);maxbands = sum(element_status);bands= zeros(1,maxbandsize);bandsizes= zeros(1,maxbands);elebandnumber = zeros(1,numel);% Now compute the sets of connected elements with our own routine% proceed element-by-element through the mesh.%  if an element has element status = 1:%    -check that element status = 1 for neighbors%    -add to this element to the list that contains the neighbor with status = 1%    -if more than one neighbor is in a set and those lists are distinct, merge the sets%    -if no neighbors are in a set, start a new set% the array bands holds the sets of connected elements% the array bandsizes holds the number of elements in each setrunningsum = 0;for iele = 1:1:numel      if(element_status(iele) == 1)         runningsum = runningsum+iele;    connectedsides=0;              if(nbands~=0)             mergeflag = 0;           for jside = 1:1:nfpe       jneigh = ele_neigh(jside,iele);               for krow = 1:1:nbands                    inexistingband = 0;             alreadyinlist = 0;            for llist = 1:1:bandsizes(krow)                if(bands(krow,llist)==jneigh)                    inexistingband = 1;                end                if(bands(krow,llist)==iele)                    alreadyinlist = 1;                end            end                        if(inexistingband==1&alreadyinlist==0)                bands(krow,bandsizes(krow)+1) = iele;                bandsizes(krow) = bandsizes(krow)+1;                modifiedband = krow;                if(elebandnumber(iele) ==0)                    elebandnumber(iele) = modifiedband;                end                mergeflag = mergeflag+1;                connectedsides = connectedsides+1;                break;            end        end         if(mergeflag==2)                      existingband = elebandnumber(iele);           if(existingband~=modifiedband);           aa = bands(existingband,[1:bandsizes(existingband)]);           ab = bands(modifiedband,[1:bandsizes(modifiedband)]);           ac = isempty(intersect(aa,ab));           if(ac ~= 1)              ad = union(aa,ab);              newbandsize = size(ad,2);              if(modifiedband<existingband)                  updatedband = modifiedband;                  deletedband = existingband;              else                  updatedband = existingband;                  deletedband = modifiedband;              end              bandsizes(updatedband) = newbandsize;              bands(updatedband,[1:newbandsize]) = ad;              bands(deletedband,:) = [];              bandsizes(deletedband)= [];              nbands = nbands-1;              elebandnumber(iele) = updatedband;              mergeflag = 1;                                    runningsumentries = sum(sum(bands));                      if(runningsum~=runningsumentries)                          display 'Missing Elements in Bands array'                          pause                      end           end                  end       end                  end  end        if(connectedsides==0)     nbands = nbands+1;     bands(nbands,1) = iele;      bandsizes(nbands) = 1;     elebandnumber(iele) = nbands;    end     end    end%  now sort the bandsizes array so the biggest are identified.% bandorder contains the sizes of bands in descending order% bigbands contains the band number associated with the band sizeif( nbands ==0)    status = ' no bands were found; check the upper and lower threshold values -- enter control_c to exit '    pauseend[bandorder,bigbands] = sort(bandsizes,'descend');numbigbands = 10;message = ['The number of bands being displayed is:   ', num2str(numbigbands)];disp(message)if(numbigbands > nbands)    numbigbands = nbands;    message = ['Fewer than ',num2str(numbigbands), 'have been detected.' ...        ' The number of bands being displayed has been reduced to:   ', num2str(nbands)];    disp(message)end% now give each element in the mesh a number corresponding to the band rank% the rank is defined as numbigbands for the largest and decreases from there% this array is given to the vtk file and used as a thresholding parameter% to plot only elements within the largest connected sets of elementselement_bands = zeros(numel,1);element_numbers = zeros(numel,1);for iele = 1:1:numel    element_numbers(iele) = iele;endfor ibb = 1:1:numbigbands  bandcode = numbigbands - ibb +1;  ibb1 = bigbands(ibb);  ibb2 = bandorder(ibb);    for jbb = 1:1:ibb2      elenumbb = bands(ibb1,jbb);      element_bands(elenumbb) = bandcode;  end    end% now construct arrays that can be used to define graphs of connected% elements using the matlab utilities% sets of links are defined band by band.  new node numbers are defined so% that the set of nodes consists only of elements in the connected setfor ibb = 1:1:numbigbands       bandnumber = bigbands(ibb);    bandsize = bandsizes(bandnumber);    band_graph_nodenames = zeros (1,bandsize);    band_graph_elements = zeros(1,numel);    numlinks = 0;    for jnode = 1:1:bandsize        node_ele = bands(bandnumber,jnode);        band_graph_nodenames(jnode) = node_ele;        band_graph_elements(node_ele) = jnode;               for kfacet = 1:1:nfpe           node_neigh = ele_neigh(kfacet,node_ele);           if(node_neigh~=0)           link_ele = [node_ele node_neigh];           [flag] = all(ismember(link_ele, bands(bandnumber,:)));           if(flag)               numlinks = numlinks+1;           end           end       end                end             band_graph_links = zeros(numlinks,2);       band_graph_link_ele = zeros(numlinks,2);               numlinks = 0;    for jnode = 1:1:bandsize        node_ele = bands(bandnumber,jnode);               for kfacet = 1:1:nfpe           node_neigh = ele_neigh(kfacet,node_ele);           if(node_neigh~=0)           knode = band_graph_elements(node_neigh);           link_ele = [node_ele node_neigh];           link_nodes = [jnode  knode  ];           [flag] = all(ismember(link_ele, bands(bandnumber,:)));           if(flag)               numlinks = numlinks+1;               band_graph_link_ele(numlinks,:) = link_ele(:);               band_graph_links(numlinks,:) = link_nodes(:);           end           end       end                end        %now remove repeats as links are defined both from elements a to b and    %from elements b to a.        band_graph_links = sort(band_graph_links,2);    band_graph_link_ele = sort(band_graph_link_ele,2);        band_graph_links_unique = unique(band_graph_links(:,1:2),'rows');    band_graph_link_ele_unique = unique(band_graph_link_ele(:,1:2),'rows');        numlinks = size(band_graph_link_ele_unique,1);    % compute and store the global mesh link number for each band link      band_global_link= zeros(1,numlinks);       for ilink = 1:1:numlinks             link_ele(:)  = band_graph_link_ele_unique(ilink,:);      iele1(:) = graph_link_inv(:,link_ele(1));        iele2(:) = graph_link_inv(:,link_ele(2));        iele_intersect = intersect(iele1,iele2);      iele_size = size(iele_intersect,2);      for isize = 1:1:iele_size      if(iele_intersect(isize) ~=0)           band_global_link(ilink) = iele_intersect(isize);      end      end   end      % create a structure file for all the graph data for this band and save   % in a .mat file.    bigbandgraphfile = Data_Structure_BigBands(band_graph_nodenames,band_graph_elements,band_graph_links_unique,...    band_graph_link_ele_unique,band_global_link);bigbandname = [framefilebasename '_bigband' num2str(ibb) '_graph.mat'];    save(bigbandname,'bigbandgraphfile');   endclear graph_links graph_link_elebandarrays    = Data_Structure_Bands(nbands,bandsizes,bands,bigbands,bandorder,element_bands);save([framefilebasename,'_bandarrays.mat'],'bandarrays');bandsdatafile = Data_Structure_VTK(element_bands,element_numbers,datafile);SUF = 'vtk';file_bands_VTK = fopen(sprintf('%s.%s', [framefilebasename '_bands'], SUF), 'w');Export_Bands_VTK(file_bands_VTK, bandsdatafile , meshfile,  phases,grains,extradatafile,coords_frame);status = 'Completed writing results to VTK file'status = 'Band Analyses Completed.  Results in .mat files; visualization in .fig and .vtk files.'